create extension if not exists pgcrypto;
create table if not exists parts (id text primary key, manufacturer text not null, name text not null, manufacturer_part_number text, category text, official_url text, status text default 'active', created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists vehicles (id text primary key, year int, make text, model text, trim text, chassis text, engine text, drivetrain text, transmission text);
create table if not exists part_fitments (id uuid primary key default gen_random_uuid(), part_id text references parts(id), vehicle_id text references vehicles(id), fitment_status text not null, confidence numeric not null check(confidence between 0 and 1), source_id text, notes text, unique(part_id,vehicle_id));
create table if not exists sources (id text primary key, part_id text references parts(id), source_type text not null, url text not null, title text, outlet text, published_at timestamptz, retrieved_at timestamptz, summary text, confidence numeric check(confidence between 0 and 1), metadata jsonb default '{}'::jsonb);
create table if not exists offers (id text primary key, part_id text references parts(id), vendor text not null, url text not null, price numeric, shipping numeric, currency text default 'USD', in_stock boolean, condition text, retrieved_at timestamptz, metadata jsonb default '{}'::jsonb);
create table if not exists price_history (id bigserial primary key, offer_id text references offers(id), price numeric, shipping numeric, in_stock boolean, captured_at timestamptz default now());
create table if not exists claims (id uuid primary key default gen_random_uuid(), source_id text references sources(id), part_id text references parts(id), claim_type text, value_num numeric, value_text text, unit text, confidence numeric check(confidence between 0 and 1), verified boolean default false, metadata jsonb default '{}'::jsonb);
create table if not exists part_relationships (id uuid primary key default gen_random_uuid(), part_id text references parts(id), related_part_id text references parts(id), relationship text not null, confidence numeric check(confidence between 0 and 1), source_id text);
create table if not exists review_queue (id text primary key, entity_type text, entity_id text, reason text, payload jsonb, severity text, created_at timestamptz default now(), resolved_at timestamptz);
create index if not exists idx_sources_part on sources(part_id); create index if not exists idx_offers_part on offers(part_id); create index if not exists idx_fitment_vehicle on part_fitments(vehicle_id);
